mapper.update:
UPDATE scheduled_jobs
SET status = 'RUNNING',
    lease_owner = #{owner},
    lease_until = #{leaseUntil},
    updated_at = #{now}
WHERE id = #{id}
  AND (
      (status IN ('READY', 'RETRY_WAIT') AND next_run_at <= #{now})
      OR (status = 'RUNNING' AND lease_until IS NOT NULL AND lease_until <= #{now})
  )

mapper.select:
SELECT *
FROM scheduled_jobs
WHERE reminder_id = #{reminderId}
  AND status = #{status}
ORDER BY id
